entries[88335] = { ["name"] = "Drache des Ostwinds", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Drachen des Ostwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Bei all seinen wahnsinnigen Bemühungen, neue Drachen zu erschaffen, hat Todesschwinge ganz vergessen, dass es noch viele unglaubliche Rassen gibt, die wir nie in Azeroth erblickt haben.\" - Thrall\nErfolg:\nRuhm des Kataklysmus-Schlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
