entries[88718] = { ["name"] = "Phosphorsteindrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Phosphorsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Die Steinmutter hat sich nie viele Gedanken über den rebellischen Aeonaxx gemacht und sogar zugelassen, dass seine Brut ihr Reich verlässt.\"\nBeute von:\nAeonaxx\nOrt:\nTiefenheim" }
