entries[88741] = { ["name"] = "Drache des Westwinds", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Drachen des Westwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Diese majestätischen Bestien nutzen die elementaren Kräfte des Sturms, knistern wie Blitze und brüllen wie der Donner.\"\nVerkäufer:\nRüstmeister Brazie\nZone:\nHalbinsel von Tol Barad\nWächter von Baradin - Ehrfürchtig" }
entries[88742] = { ["name"] = "Drache des Nordwinds", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Drachen des Nordwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Wer den Sturm kennt wird der Ruhe überdrüssig.\"\nBeute von:\nAltairus\nZone:\nDer Vortexgipfel" }
entries[88744] = { ["name"] = "Drache des Südwinds", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Drachen des Südwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Wie eine zarte Brise im Sommer. Aber das will nicht viel heißen, wenn man bedenkt, woher sie kommt. - Itesh\"\nBeute von:\nAl'Akir\nZone:\nThron der Vier Winde" }
entries[88746] = { ["name"] = "Vitriolsteindrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Vitriolsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Die wären perfekt für einen Anhänger geeignet, und das da würde einen fantastischen Ring ergeben. Lasst mich wissen, wenn das Ding sich häutet oder so. - Kalinda\"\nBeute von:\nPlattenhaut\nZone:\nDer Steinerne Kern" }
entries[88747] = { ["name"] = "Wildpilz", ["text"] = "40 Meter Reichweite\nSofort 30 sek. Wiederaufladung\n3 Aufladungen\nLässt an der Position des gegnerischen Ziels einen magischen Pilz wachsen. Nach 1 Sek. detoniert der Pilz, verursacht (254.4% der Zaubermacht) Naturschaden und anschließend im Verlauf von 10 Sek. zusätzlich (143.5% der Zaubermacht) Naturschaden. Betroffene Ziele werden um 50% verlangsamt.\n\nErzeugt abhängig von den getroffenen Zielen bis zu 20 Astrale Macht." }
entries[88748] = { ["name"] = "Braunes Reitkamel", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares braunes Reitkamel oder gibt es wieder frei.\n\"An einem einzigen Nachmittag hat Fennimore Quigley als Erster ein Kamel gemolken und kurz darauf auch noch den Rekord für den längsten unbeabsichtigten Flug gebrochen.\"\nVerkäufer:\nSchmied Abasi\nZone:\nUldum\nRamkahen - Ehrfürchtig\nKosten:\n100" }
