entries[88929] = { ["name"] = "Schwarzer Trilobit", ["text"] = "Wirken in 2 sek. 5\nTrilobiten sind ausgestorbene Krebstiere, die einst sehr artenreich und in großer Zahl auf Azeroth vertreten waren. Es halten sich Legenden, dass es noch immer Trilobiten von angeblich epischen Ausmaßen gibt.\nSchwarzer Trilobit\nWird beim Aufheben gebunden" }
entries[88930] = { ["name"] = "Schöner konservierter Farn", ["text"] = "Wirken in 2 sek. 5\nFarne sind primitive Pflanzen, die Stämme, Blätter und Wurzeln besitzen, jedoch keine Samen oder Blüten. Sie reproduzieren sich mit Hilfe von Sporen, ähnlich den Pilzen. In früherer Zeit nahmen Farne die ökologische Nische ein, die heute Blütenpflanzen innehaben.\nSchöner konservierter Farn\nWird beim Aufheben gebunden" }
