entries[89009] = { ["name"] = "Schminkschatulle einer Hochgeborenen", ["text"] = "Wirken in 2 sek. 5\nDieses Kistchen aus feinem Porzellan wurde wahrscheinlich genutzt, um Kosmetik, Schmuck oder andere kleine Kostbarkeiten einer Hochgeborenen aufzubewahren. Der aus Silber gefertigte Verschluss zeigt zwei Eicheln und ein Stechpalmenblatt.\nSchminkschatulle einer Hochgeborenen\nWird beim Aufheben gebunden" }
